const navItems = [['/','Home'],['/about','About Us'],['/services','Services'],['/projects','Projects'],['/request-a-quote','Request a Quote'],['/contact','Contact']];
function serviceHref(s){return `/services#${s.slug}`;}
function whatsapp(text){return `${WA}?text=${encodeURIComponent(text)}`;}
function btn(label,href,kind='primary',icon='arrow'){return `<a class="btn btn-${kind}" href="${href}">${icon?ico(icon,17):''}<span>${label}</span></a>`;}
function sectionHeading(eyebrow,headline,sub=''){return `<div class="section-heading"><span class="eyebrow">${eyebrow}</span><h2>${headline}</h2>${sub?`<p>${sub}</p>`:''}</div>`;}
function header(){return `<header class="site-header"><div class="container header-inner"><a href="/" class="brand" aria-label="Eagle Construction Company Home"><span class="brand-mark"><img src="/assets/eagle-head.png" alt="Eagle Construction Company eagle emblem" /></span><span class="brand-type"><span>EAGLE</span><small>CONSTRUCTION COMPANY</small></span></a><nav class="desktop-nav" aria-label="Main navigation">${navItems.map(([url,title])=>`<a href="${url}" class="${(page===url?'active':'')} nav-link">${title}${title==='Services'?ico('chevron',12):''}</a>`).join('')}</nav><a class="header-whatsapp" href="${whatsapp('Hello Eagle Construction Company, I would like to enquire about your services.')}" target="_blank" rel="noopener">${ico('whatsapp',20)} <span>${PHONE_DISPLAY}</span></a><button id="menu-toggle" class="menu-toggle" aria-label="Open navigation" aria-expanded="false">${ico('menu',25)}</button></div><nav id="mobile-nav" class="mobile-nav" aria-label="Mobile navigation">${navItems.map(([url,title])=>`<a href="${url}">${title}${ico('arrow',17)}</a>`).join('')}<a href="tel:+${PHONE_DIGITS}" class="mobile-call">${ico('phone',19)} Call ${PHONE_DISPLAY}</a></nav></header>`;}
function footer(){return `<footer class="site-footer"><div class="container footer-grid"><div class="footer-logo"><div class="footer-brand">${ico('house',35)}<strong>EAGLE <span>CONSTRUCTION</span></strong></div><small>COMPANY</small></div><p class="footer-intro">Building your dreams into reality with quality workmanship, reliable service and lasting results.</p><div class="footer-links"><b>Quick Links</b><a href="/">Home</a><a href="/about">About Us</a><a href="/services">Services</a><a href="/projects">Projects</a></div><div class="footer-links"><b>Services</b>${mainServices.map(s=>`<a href="${serviceHref(s)}">${s.name}</a>`).join('')}</div><div class="footer-links footer-contact"><b>Contact Us</b><a href="tel:+${PHONE_DIGITS}">${ico('phone',14)} ${PHONE_DISPLAY}</a><a href="${WA}" target="_blank" rel="noopener">${ico('whatsapp',14)} WhatsApp Us</a><a href="mailto:${EMAIL}">${ico('mail',14)} ${EMAIL}</a></div></div><div class="footer-bottom"><div class="container"><span>© ${new Date().getFullYear()} Eagle Construction Company. All rights reserved.</span><span>Your Vision · Our Expertise · Lasting Results</span></div></div></footer>`;}
function hero({name='home',tagline,heading,description}){return `<section class="hero hero-${name}"><div class="hero-image" style="background-image:url('${asset('hero-'+name)}')"></div><div class="container hero-inner"><div class="hero-copy"><span class="eyebrow">${tagline} <span class="eyebrow-line"></span></span><h1>${heading}</h1><p>${description}</p><div class="hero-actions">${btn('Get a Quote on WhatsApp',whatsapp('Hello Eagle Construction Company, I would like a quotation.'),'primary','whatsapp')}${btn(PHONE_DISPLAY,`tel:+${PHONE_DIGITS}`,'outline','phone')}</div></div></div></section>`;}
function intro(title,description){return `<section class="intro-strip"><div class="container intro-grid"><h2>${title}</h2><p>${description}</p></div></section>`;}
function serviceCards(items=mainServices,variant='standard'){return `<div class="service-cards ${variant}">${items.map(s=>`<a class="service-card" id="${s.slug}" href="${serviceHref(s)}"><div class="service-photo"><img src="${asset(s.image)}" alt="${s.name} service" loading="lazy"/></div><div class="service-body"><span class="service-icon">${ico(s.icon,25)}</span><h3>${s.name}</h3><p>${s.short}</p>${variant==='details'?`<span class="learn-more">Learn More ${ico('arrow',15)}</span>`:''}</div></a>`).join('')}</div>`;}
const exampleProjects=[
 {name:'Residential Construction',image:'project-house',desc:'Homes designed around the way you live.'},
 {name:'Swimming Pool Spaces',image:'project-pool',desc:'Outdoor spaces for leisure and comfort.'},
 {name:'Bathroom Improvements',image:'project-bath',desc:'Practical, attractive bathroom finishes.'},
 {name:'Flooring & Tiling',image:'project-floor',desc:'Neatly completed interior floors.'}
];
function projectsStrip(){return `<section class="section projects-strip"><div class="container"><div class="heading-row"><div><span class="eyebrow">OUR PROJECT AREAS</span><h2>Construction & Renovation Inspiration</h2><p>Explore the kinds of spaces we can help you create.</p></div>${btn('Explore Services','/projects','outline','arrow')}</div><div class="project-gallery">${exampleProjects.map(p=>`<a href="/projects" class="project-photo" aria-label="${p.name}"><img src="${asset(p.image)}" alt="${p.name} example" loading="lazy" /><span>${p.name}</span></a>`).join('')}</div></div></section>`;}
function quoteBanner(){return `<section class="quote-banner"><div class="container quote-banner-grid"><div class="quote-banner-icon">${ico('upload',52)}</div><div><h2>Request a Quotation & Upload Your Building Plans</h2><p>Have a project in mind? Tell us about your plans and attach drawings to request a clear, no-obligation quotation.</p>${btn('Upload Plans & Request a Quote','/request-a-quote','primary','upload')}</div><div class="blueprint-image"></div></div></section>`;}
function visitBanner(){return `<section class="visit-banner"><div class="visit-image" style="background-image:url('${asset('workers')}')"></div><div class="visit-content"><span class="visit-icon">${ico('calendar',31)}</span><div><h2>Book a Site Visit</h2><p>Discuss your project on-site with our team, get advice and plan the right solution for your building needs.</p><button data-modal="visit" class="btn btn-primary">${ico('calendar',17)} Book a Site Visit ${ico('arrow',16)}</button></div></div></section>`;}
function steps(servicesPage=false){let arr=servicesPage?[['message','Discuss Your Needs','Tell us what you have in mind.'],['pin','Site Visit & Assessment','We assess the work and provide advice.'],['list','Detailed Quotation','Receive an estimate for the project.'],['hardhat','Construction & Updates','We work with you as the build progresses.'],['check','Project Completion','The project is finished and reviewed.']]:[['message','Tell Us Your Idea','Share your requirements and project details.'],['file','Get a Quotation','Receive a clear estimate for your project.'],['hardhat','We Build','Our team gets to work on your project.'],['check','Project Completed','Enjoy your finished space, built with care.']];return `<section class="section process-section">${sectionHeading('OUR PROCESS',servicesPage?'A Simple, Clear Work Process':'A Simple, Clear Process','From your idea to a finished project, we make the steps easy to understand.')}<div class="container process-steps">${arr.map(([ic,t,d],i)=>`<div class="process-step"><div>${ico(ic,34)}</div><h3>${i+1}. ${t}</h3><p>${d}</p></div>${i===arr.length-1?'':`<span class="step-arrow">${ico('arrow',23)}</span>`}`).join('')}</div></section>`;}
function benefits(){return `<section class="benefits"><div class="container benefits-grid"><div><span class="eyebrow">WHY CHOOSE US</span><h2>A Reliable Partner<br>for Your Building Project</h2><p>Eagle Construction Company combines hands-on workmanship and a customer-focused approach to make your building vision a reality.</p></div><ul>${['Quality workmanship','Reliable, professional service','Clear communication and quotations','Attention to safety and detail','A focus on lasting results'].map(v=>`<li>${ico('check',17)} ${v}</li>`).join('')}</ul><img src="${asset('house-feature')}" alt="Modern residential home design" loading="lazy"></div></section>`;}
function commitments(){return `<section class="section commitments-section">${sectionHeading('WHAT MATTERS TO US','Our Commitment to Every Client','The qualities that guide each project, from the first conversation to completion.')}<div class="container commitment-cards"><article><span class="quote-mark">“</span><p>Quality workmanship and care in every stage of construction and renovation.</p><b>QUALITY BUILDS LAST</b><span class="little-stars">✦ ✦ ✦</span></article><article><span class="quote-mark">“</span><p>Clear communication, practical advice, and dependable support for your project.</p><b>RELIABLE SERVICE</b><span class="little-stars">✦ ✦ ✦</span></article><article><span class="quote-mark">“</span><p>From small repairs to larger building projects, every detail deserves attention.</p><b>BUILT WITH PURPOSE</b><span class="little-stars">✦ ✦ ✦</span></article></div></section>`;}
function home(){return `${hero({name:'home',tagline:'EAGLE CONSTRUCTION COMPANY',heading:'Trusted Construction<br>& Renovation Experts',description:'Quality construction, renovations and home improvements that add lasting value to your property.'})}${intro('Building Better<br>Spaces for Your Life','Eagle Construction Company offers building and improvement services for homes and properties. From new house construction to painting, plumbing, electrical work, solar installation, swimming pools and tiling, we help you create spaces built to last.')}<section class="section services-section">${sectionHeading('OUR SERVICES','Complete Construction Solutions','A full range of building and home improvement services, delivered with quality and care.')}<div class="container">${serviceCards()}</div><div class="view-all">${btn('View All 10 Services','/services','outline','arrow')}</div></section>${projectsStrip()}${quoteBanner()}${visitBanner()}${steps()}${benefits()}${commitments()}`;}
function values(){return `<section class="section values-section">${sectionHeading('OUR FOUNDATION','Our Mission, Vision and Values')}<div class="container value-cards"><article>${ico('target',39)}<div><h3>Our Mission</h3><p>To provide quality construction and renovation services that help our clients create safe, functional and lasting spaces.</p></div></article><article>${ico('eye',39)}<div><h3>Our Vision</h3><p>To be a trusted construction partner recognised for reliable service and workmanship that stands the test of time.</p></div></article><article>${ico('diamond',39)}<div><h3>Our Values</h3><ul>${['Quality workmanship','Honesty and communication','Reliable service','Safety and responsibility','Customer satisfaction'].map(x=>`<li>${ico('check',15)} ${x}</li>`).join('')}</ul></div></article></div></section>`;}
function about(){return `${hero({name:'about',tagline:'ABOUT EAGLE CONSTRUCTION',heading:'About Eagle<br>Construction Company',description:'A building and renovation partner focused on quality, dependable service and practical solutions that last.'})}${intro('Building Homes<br>and Spaces That Last','Eagle Construction Company helps homeowners and property owners bring building ideas to life. Our services include new builds, renovations, plumbing, electrical installations, roofing, painting, tiling, swimming pools and solar installation.')}<section class="section about-services"><div class="container">${serviceCards()}</div></section>${values()}<section class="people-section"><div class="people-photo" style="background-image:url('${asset('workers-about')}')"></div><div class="people-copy"><span class="eyebrow">OUR PEOPLE</span><h2>Skilled Workmanship<br>& Project Supervision</h2><p>Our approach puts careful planning, responsible work and clear client communication at the centre of each project — from initial discussion through to completion.</p>${btn('Talk to Our Team','/contact','primary','users')}</div></section><section class="section journey-section">${sectionHeading('OUR APPROACH','From Your Idea to a Lasting Space','A straightforward way to move from your first enquiry to a project you can be proud of.')}<div class="container journey-items">${[['sparkle','Your Idea','Share your vision and the work you need done.'],['hardhat','Project Planning','We discuss the right approach for your site and requirements.'],['shield','Quality Focus','Good workmanship and thoughtful supervision guide the job.'],['star','Lasting Results','Our goal is a finish that adds value to your property.']].map(([ic,t,d])=>`<article><span>${ico(ic,30)}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section>${benefits()}<section class="stat-band"><div class="container stat-grid"><div>${ico('settings',36)}<b>10</b><small>Service Categories</small></div><div>${ico('house',36)}<b>Homes</b><small>Construction & Renovations</small></div><div>${ico('shield',36)}<b>Quality</b><small>Workmanship Focus</small></div><div>${ico('check',36)}<b>Care</b><small>From Start to Finish</small></div></div></section>${commitments()}`;}
function specialCard(s){return `<a href="/request-a-quote?service=${encodeURIComponent(s.name)}" class="special-card" id="${s.slug}"><img src="${asset(s.image)}" alt="${s.name}" loading="lazy"><div class="special-copy"><div>${ico(s.icon,30)}</div><h3>${s.name}</h3><p>${s.short}</p><span>Request a Quote ${ico('arrow',15)}</span></div></a>`;}
function servicesPage(){return `${hero({name:'services',tagline:'OUR SERVICES',heading:'Complete<br>Construction<br>Solutions',description:'Quality construction, renovations and home improvement services for properties of all sizes.'})}${intro('Our Construction<br>Services','Eagle Construction Company provides a wide range of practical building solutions, from new houses and renovations to electrical installations, roofing, painting, solar, tiling and pools — all guided by a commitment to quality.')}<section class="section core-services">${sectionHeading('OUR CORE SERVICES','Key Services We Offer','Building and improvement services for your home or property.')}<div class="container">${serviceCards(mainServices,'details')}</div></section><section class="section special-section"><div class="container"><div class="section-split"><div><span class="eyebrow">MORE THAN CONSTRUCTION</span><h2>Specialised Services<br>for Complete Projects</h2></div><p>Beyond house construction and renovations, our team offers further services to help you plan, build, finish and improve your property.</p></div><div class="special-grid">${extraServices.map(specialCard).join('')}${specialCard({name:'Building Plans & Consultation',slug:'building-consultation',icon:'file',image:'quote-blueprints',short:'Share your drawings or discuss plans for your building project.'})}</div><div class="management"><img src="${asset('project-management')}" alt="Construction project supervision"/><div>${ico('list',28)}<h3>Project Management & Coordination</h3><p>We work to keep construction and renovation activities coordinated, with clear project communication and a focus on quality.</p><div class="management-benefits">${['Planning & coordination','Workmanship focus','Project updates'].map(t=>`<span>${ico('check',16)} ${t}</span>`).join('')}</div></div></div></div></section>${steps(true)}${projectsStrip()}${quoteBanner()}`;}
function projectsPage(){return `${hero({name:'home',tagline:'PROJECT AREAS',heading:'Spaces Worth<br>Building For',description:'Explore construction and renovation possibilities, from new homes to indoor finishes and outdoor living.'})}${intro('Your Project,<br>Our Expertise','Every project begins with an idea. Whether you are planning a new home, improving an existing property, building a swimming pool or refreshing interiors, Eagle Construction Company is ready to discuss your needs.')}<section class="section project-page-section">${sectionHeading('PROJECT INSPIRATION','What We Can Help You Create','Illustrative images of the types of work offered. Contact us for a verified portfolio of completed Eagle Construction projects.')}<div class="container project-page-grid">${[...exampleProjects,{name:'Interior Finishes',image:'interior-finishes',desc:'Bright, comfortable living spaces.'},{name:'Roofing',image:'roofing',desc:'Strong, carefully planned roofing.'},{name:'Electrical Installations',image:'electrical',desc:'Powering modern properties.'},{name:'Solar Installation',image:'solar',desc:'Solar options for your energy needs.'}].map(p=>`<article class="project-item"><img src="${asset(p.image)}" alt="${p.name} illustration" loading="lazy"><div><h3>${p.name}</h3><p>${p.desc}</p></div></article>`).join('')}</div></section>${quoteBanner()}${steps()}`;}
function servicesOverview(){return `<section class="section contact-services">${sectionHeading('OUR SERVICES','Construction & Renovation Solutions','Whatever your building requirements, we would be happy to hear from you.')}<div class="container compact-services">${mainServices.map(s=>`<a href="${serviceHref(s)}">${ico(s.icon,30)}<h3>${s.name}</h3><p>${s.short}</p></a>`).join('')}</div></section>`;}
function quotationForm(isDedicated=false){return `<form id="quote-form" class="quote-form" method="POST" enctype="multipart/form-data"><div class="form-heading"><h2>Request a Quote</h2><p>Tell us about your project and we’ll review your details and contact you to discuss the next steps.</p></div><div class="form-fields"><label>Full Name <span>*</span><input type="text" name="name" required minlength="2" maxlength="120" placeholder="Enter your full name" autocomplete="name"></label><label>Phone Number <span>*</span><input type="tel" name="phone" required minlength="8" maxlength="25" placeholder="e.g. 071 234 5678" autocomplete="tel"></label><label>Email Address <span>*</span><input type="email" name="email" required maxlength="180" placeholder="Enter your email address" autocomplete="email"></label><label>Service Needed <span>*</span><select name="service" required><option value="">Select a service</option>${services.map(s=>`<option value="${s.name}">${s.name}</option>`).join('')}<option value="Building Plans & Consultation">Building Plans & Consultation</option><option value="Other / Not Sure">Other / Not Sure</option></select></label><label class="field-full">Project Location <span>*</span><input type="text" name="location" required maxlength="180" placeholder="e.g. Harare, Chitungwiza, Ruwa, etc."></label><label class="field-full">Message / Project Details <span>*</span><textarea name="details" required minlength="10" maxlength="3000" placeholder="Tell us about your project (type of work, size, timeframe, specific requirements, etc.)"></textarea></label><label class="field-full">Upload Building Plans or Drawings <em>(Optional)</em><span class="upload-field" id="upload-field">${ico('upload',38)}<b id="upload-label">Choose files or drop them here</b><small>PDF, DWG, JPG or PNG · Up to 10 MB per file · Up to 3 files</small><input type="file" name="plans" id="plans" accept=".pdf,.dwg,.jpg,.jpeg,.png" multiple></span></label><label class="spam-trap" aria-hidden="true">Website<input type="text" name="company_website" autocomplete="off" tabindex="-1"></label></div><div class="form-note">Your details will only be used to respond to your enquiry. We do not request deposits through this form.</div><button type="submit" class="btn btn-primary submit-btn">${ico('arrow',19)} Send Quotation Request</button><div role="status" aria-live="polite" id="form-message"></div></form>`;}
function contactCards(){return `<aside class="contact-aside"><div class="contact-card"><span>${ico('whatsapp',40)}</span><h3>Contact Us on WhatsApp</h3><p>Get a quick response, ask a question or discuss a quotation directly on WhatsApp.</p>${btn(PHONE_DISPLAY,whatsapp('Hello Eagle Construction Company. I would like to ask about a building project.'),'primary','whatsapp')}</div><div class="contact-card visit-card"><span>${ico('calendar',38)}</span><h3>Book a Site Visit</h3><p>Discuss your project on-site with our team and get helpful advice for your next steps.</p><button class="btn btn-primary" data-modal="visit">Book a Site Visit ${ico('arrow',17)}</button><img src="${asset('workers')}" alt="Construction workers planning a site visit" loading="lazy"/></div></aside>`;}
function contactBottom(){return `<section class="contact-information"><div class="container contact-info-grid"><div class="info-block">${ico('phone',30)}<h3>Call or WhatsApp</h3><b><a href="tel:+${PHONE_DIGITS}">${PHONE_DISPLAY}</a></b><p>Reach out to discuss your project and arrange a consultation.</p></div><div class="info-graphic"><img src="${asset('house-feature')}" alt="Example home construction" loading="lazy"/><span>Quality Builds Last!</span></div><div class="info-block">${ico('mail',29)}<h3>Email Us</h3><a class="email-wrap" href="mailto:${EMAIL}">${EMAIL}</a><p>For enquiries, project briefs and building-related questions.</p></div></div></section>`;}
function faqs(){const faq=[['Is the quotation free and without obligation?','You can submit a request without obligation. Our team will clarify the project details and any assessment requirements before preparing a quotation.'],['Do you offer site visits?','You can request a site visit using the booking form. We will contact you to discuss the location, availability and any applicable charges.'],['How long does it take to receive a quotation?','The time depends on the scale and information available. Please provide as many details and drawings as possible so our team can respond accurately.'],['Which areas do you service?','Please share your project location when you enquire. The team will confirm whether the location can be served.'],['Can I upload my building plans?','Yes. PDF, DWG, JPG and PNG files are supported (maximum three files, 10 MB each).']];return `<section class="section faq-section">${sectionHeading('FAQ','Frequently Asked Questions','Helpful answers about quotations, services and site visits.')}<div class="container faq-grid"><img src="${asset('hero-contact')}" alt="Modern home exterior" loading="lazy"/><div class="faq-items">${faq.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}${ico('chevron',20)}</summary><p>${a}</p></details>`).join('')}</div></div></section>`;}
function contact(){return `${hero({name:'contact',tagline:'CONTACT EAGLE CONSTRUCTION',heading:'Let’s Build Your<br>Project Together',description:'Get in touch, request a quotation or arrange a site visit. We’re here to help bring your construction ideas to life.'})}<section class="section contact-main"><div class="container contact-grid">${contactCards()}${quotationForm()}</div></section>${servicesOverview()}${contactBottom()}${faqs()}`;}
function quotePage(){return `${hero({name:'contact',tagline:'REQUEST A QUOTE',heading:'Tell Us About<br>Your Next Project',description:'Share your project details and building drawings so we can discuss your requirements and prepare your quotation.'})}<section class="section quote-page-main"><div class="container quote-page-grid">${quotationForm(true)}<aside class="quote-side-info"><h2>How It Works</h2>${[['file','Describe the project','Tell us what needs to be built, installed or improved.'],['upload','Attach drawings','Optional plans can help us understand your requirements.'],['phone','We follow up','Our team will contact you to discuss your enquiry.']].map(([ic,t,d])=>`<div class="quote-side-step">${ico(ic,26)}<div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}<div class="aside-whatsapp"><h3>Prefer WhatsApp?</h3><p>Send us a direct message instead.</p>${btn('Chat on WhatsApp',whatsapp('Hello Eagle Construction Company, I would like a quotation.'),'primary','whatsapp')}</div></aside></div></section>${servicesOverview()}`;}
function modalHtml(){return `<div class="modal-backdrop" id="visit-modal" role="presentation" hidden><div class="modal-dialog" role="dialog" aria-modal="true" aria-labelledby="visit-title"><button class="modal-close" id="modal-close" aria-label="Close">${ico('x',22)}</button><span class="eyebrow">PROJECT CONSULTATION</span><h2 id="visit-title">Request a Site Visit</h2><p>Send your details and we’ll contact you to agree a suitable time and location.</p><form id="visit-form"><label>Your Name <span>*</span><input name="name" type="text" maxlength="120" required placeholder="Full name"></label><label>Phone Number <span>*</span><input name="phone" type="tel" minlength="8" maxlength="25" required placeholder="Your phone number"></label><label>Project Location <span>*</span><input name="location" type="text" maxlength="180" required placeholder="Where is the project located?"></label><label>Preferred Date <span>*</span><input name="preferred_date" type="date" required></label><label>Project Details <span>*</span><textarea name="details" minlength="10" maxlength="3000" required placeholder="What would you like our team to assess?"></textarea></label><label class="spam-trap" aria-hidden="true">Website<input type="text" name="company_website" tabindex="-1"></label><button type="submit" class="btn btn-primary submit-btn">${ico('calendar',18)} Request Site Visit</button><div id="visit-message" role="status" aria-live="polite"></div></form></div></div>`;}
function adminPage(){return `<section class="admin-page"><div class="container"><span class="eyebrow">SECURE ADMINISTRATION</span><h1>Eagle Construction Enquiries</h1><p>Review quotation and site-visit requests submitted through this website.</p><div id="admin-auth"><form id="admin-login" class="admin-login"><label>Admin Password<input type="password" name="password" required autocomplete="current-password"></label><button type="submit" class="btn btn-primary">${ico('lock',18)} Sign In</button><div id="admin-error" role="status"></div></form></div><div id="admin-dash" hidden><div class="admin-actions"><button id="refresh-leads" class="btn btn-outline">Refresh Enquiries</button><button id="admin-logout" class="btn btn-outline">Sign Out</button></div><div class="admin-table-wrap"><table><thead><tr><th>Received</th><th>Type</th><th>Name</th><th>Phone</th><th>Service / Date</th><th>Location</th><th>Details & Files</th></tr></thead><tbody id="leads-table"></tbody></table></div></div></div></section>`;}
const routes={'/':home,'/about':about,'/services':servicesPage,'/projects':projectsPage,'/contact':contact,'/request-a-quote':quotePage,'/admin':adminPage};
function render(){if(eagleAnimationContext){eagleAnimationContext.revert();eagleAnimationContext=null;}page = window.location.pathname.replace(/\/$/,'')||'/';if(!routes[page])page='/';document.title=({ '/':'Eagle Construction Company | Quality Builds Last','/about':'About Eagle Construction Company','/services':'Construction Services | Eagle Construction Company','/projects':'Project Areas | Eagle Construction Company','/contact':'Contact | Eagle Construction Company','/request-a-quote':'Request a Quote | Eagle Construction Company','/admin':'Admin Enquiries | Eagle Construction Company'})[page];app.innerHTML=header()+`<main id="main">${routes[page]()}</main>`+footer()+modalHtml();document.body.classList.remove('menu-open');menuOpen=false;eagleInitMenu();bindUI();const serviceFromUrl=new URLSearchParams(location.search).get('service');if(serviceFromUrl){const select=document.querySelector('#quote-form select[name="service"]');if(select)select.value=serviceFromUrl;}if(location.hash){requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView({behavior:'instant',block:'center'}));}else window.scrollTo({top:0,behavior:'instant'});eagleAfterRender();}
function navigate(path){if(eagleShouldTransition(path)){eagleTransition(()=>{window.history.pushState({},'',path);render();},path);return;}window.history.pushState({},'',path);render();}
function bindUI(){document.getElementById('menu-toggle')?.addEventListener('click',()=>{const nav=document.getElementById('mobile-nav');menuOpen=!menuOpen;nav.classList.toggle('shown',menuOpen);document.getElementById('menu-toggle').setAttribute('aria-expanded',String(menuOpen));document.body.classList.toggle('menu-open',menuOpen)});document.querySelectorAll('a[href^="/"]').forEach(a=>a.addEventListener('click',e=>{const href=a.getAttribute('href');if(!href.startsWith('//')&&e.button===0&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey){e.preventDefault();menuOpen=false;navigate(href);}}));document.querySelectorAll('[data-modal="visit"]').forEach(btn=>btn.addEventListener('click',openModal));document.getElementById('modal-close').addEventListener('click',closeModal);document.getElementById('visit-modal').addEventListener('click',e=>{if(e.target.id==='visit-modal')closeModal()});document.getElementById('quote-form')?.addEventListener('submit',submitQuote);document.getElementById('visit-form')?.addEventListener('submit',submitVisit);document.getElementById('plans')?.addEventListener('change',updateFileLabel);if(page==='/admin')setupAdmin();const date=document.querySelector('[name="preferred_date"]');if(date)date.min=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);}
function openModal(){document.getElementById('visit-modal').hidden=false;document.body.classList.add('modal-open');document.querySelector('.modal-close').focus();}
function closeModal(){document.getElementById('visit-modal').hidden=true;document.body.classList.remove('modal-open');}
function updateFileLabel(e){const files=[...e.target.files];const label=document.getElementById('upload-label');if(files.length>3||files.some(f=>f.size>10*1024*1024)){label.textContent='Maximum 3 files, 10 MB each';label.classList.add('error-text');e.target.value='';return;}label.classList.remove('error-text');label.textContent=files.length?files.map(f=>f.name).join(' · '):'Choose files or drop them here';}
async function submitQuote(e){e.preventDefault();const form=e.target;const status=document.getElementById('form-message');const button=form.querySelector('[type="submit"]');status.textContent='';const files=[...form.querySelector('[type="file"]').files];if(files.length>3||files.some(f=>f.size>10*1024*1024)){status.textContent='Please choose no more than 3 files, each under 10 MB.';return;}button.disabled=true;button.classList.add('loading');const original=button.innerHTML;button.textContent='Sending your request…';try{const response=await fetch('/api/quote',{method:'POST',body:new FormData(form)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Unable to submit');status.innerHTML=`<div class="success-message">${ico('check',20)} Your request was received. Reference: <strong>${data.reference}</strong>. The team can now review your details. <a href="${whatsapp(`Hello Eagle Construction Company, I have submitted quotation request ${data.reference}.`)}" target="_blank" rel="noopener">Continue on WhatsApp ${ico('arrow',15)}</a></div>`;form.reset();updateFileLabel({target:form.querySelector('#plans')});}catch(err){status.textContent=`Could not send your request: ${err.message}. You can contact the team on WhatsApp or by phone.`;status.classList.add('error-text');}finally{button.disabled=false;button.classList.remove('loading');button.innerHTML=original;}}
async function submitVisit(e){e.preventDefault();const form=e.target,button=form.querySelector('[type="submit"]'),status=document.getElementById('visit-message');button.disabled=true;status.textContent='Submitting site visit request…';try{const fields=Object.fromEntries(new FormData(form));const res=await fetch('/api/site-visit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(fields)});const d=await res.json();if(!res.ok)throw new Error(d.error||'Submission failed');status.innerHTML=`<div class="success-message">${ico('check',18)} Your site visit request was received. Reference: <b>${d.reference}</b></div>`;form.reset();}catch(err){status.textContent=err.message;status.classList.add('error-text');}finally{button.disabled=false;}}
function sanitize(s){return String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');}
async function setupAdmin(){document.getElementById('admin-login').addEventListener('submit',async e=>{e.preventDefault();const password=new FormData(e.target).get('password');const res=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});if(res.ok){e.target.reset();loadLeads();}else{const d=await res.json();document.getElementById('admin-error').textContent=d.error||'Unable to sign in';}});document.getElementById('refresh-leads').addEventListener('click',loadLeads);document.getElementById('admin-logout').addEventListener('click',async()=>{await fetch('/api/admin/logout',{method:'POST'});document.getElementById('admin-auth').hidden=false;document.getElementById('admin-dash').hidden=true;});loadLeads();}
async function loadLeads(){const res=await fetch('/api/admin/leads');if(!res.ok){document.getElementById('admin-auth').hidden=false;document.getElementById('admin-dash').hidden=true;return;}const leads=await res.json();document.getElementById('admin-auth').hidden=true;document.getElementById('admin-dash').hidden=false;document.getElementById('leads-table').innerHTML=leads.length?leads.map(l=>`<tr><td>${sanitize(new Date(l.createdAt).toLocaleString())}<br><small>${sanitize(l.reference)}</small></td><td>${sanitize(l.type)}</td><td>${sanitize(l.name)}</td><td><a href="tel:${sanitize(l.phone)}">${sanitize(l.phone)}</a><br><small>${sanitize(l.email||'')}</small></td><td>${sanitize(l.service||l.preferred_date||'—')}</td><td>${sanitize(l.location)}</td><td>${sanitize(l.details)}${l.files?.length?`<div class="download-links">${l.files.map((f,i)=>`<a href="/api/admin/download/${encodeURIComponent(l.id)}/${i}">${ico('file',14)} ${sanitize(f.originalName)}</a>`).join('')}</div>`:''}</td></tr>`).join(''):'<tr><td colspan="7">No enquiries submitted yet.</td></tr>';}

/* Eagle Construction: motion layer — menu, blueprint loader, scroll and subpage transitions only */
let eagleAnimationContext=null,eagleMotionLibrariesRequested=false,eagleMotionReady=false,eagleInitialLoaderStarted=false,eagleTransitionBusy=false,eagleSmoothScroll=null,eagleProgressInstalled=false;
const eagleReduceMotion=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function eagleInitMenu(){
 const nav=document.getElementById('mobile-nav'),toggle=document.getElementById('menu-toggle');if(!nav||!toggle)return;
 nav.className='eagle-menu';
 const sub={'/':'THE WELCOME','/about':'OUR STORY','/services':'WHAT WE DO','/projects':'PROJECT AREAS','/request-a-quote':'START YOUR BUILD','/contact':'GET IN TOUCH'};
 nav.innerHTML='<button type="button" id="eagle-menu-close" class="eagle-menu-close" aria-label="Close navigation"><span aria-hidden="true">×</span> CLOSE</button>'+
 '<div class="eagle-menu-main"><span class="eagle-menu-tag">EAGLE / SITE INDEX</span><div class="eagle-menu-list">'+
 navItems.map(([path,label],i)=>'<a class="eagle-menu-link'+(page===path?' is-current':'')+'" href="'+path+'"'+(page===path?' aria-current="page"':'')+'><span class="eagle-menu-no">0'+(i+1)+'</span><span class="eagle-menu-name">'+label+'</span></a>').join('')+
 '</div><span class="eagle-menu-foot">BUILD · RENOVATE · IMPROVE</span></div>'+
 '<div class="eagle-menu-side"><div class="eagle-menu-emblem"><img src="/assets/eagle-head.png" alt="" /></div><span class="eagle-menu-side-tag" id="eagle-menu-preview">'+(sub[page]||'EXPLORE OUR WORK')+'</span><h3>Building spaces.<br>Creating futures.</h3><p>Expertise, craftsmanship and clear communication — every step of the way.</p><a class="eagle-menu-side-contact" href="tel:+'+PHONE_DIGITS+'">Talk to our team ↗</a></div>';
 toggle.innerHTML='<span class="eagle-toggle-label">Explore</span><span class="eagle-toggle-lines" aria-hidden="true"><i></i></span>';
 toggle.setAttribute('aria-label','Open site navigation');toggle.setAttribute('aria-controls','mobile-nav');
 nav.querySelector('#eagle-menu-close').addEventListener('click',e=>{e.preventDefault();eagleCloseMenu();});
 nav.addEventListener('pointerover',e=>{const link=e.target.closest('.eagle-menu-link'),preview=document.getElementById('eagle-menu-preview');if(link&&preview)preview.textContent=sub[link.getAttribute('href')]||'EXPLORE OUR WORK';});
 toggle.addEventListener('click',()=>window.setTimeout(()=>{if(menuOpen)nav.querySelector('.eagle-menu-link')?.focus({preventScroll:true});},0));
}
function eagleCloseMenu(){
 const nav=document.getElementById('mobile-nav'),toggle=document.getElementById('menu-toggle');
 menuOpen=false;nav?.classList.remove('shown');toggle?.setAttribute('aria-expanded','false');document.body.classList.remove('menu-open');toggle?.focus({preventScroll:true});
}
function eagleShouldTransition(destination){
 if(eagleReduceMotion()||eagleTransitionBusy)return false;
 const next=new URL(destination,window.location.href).pathname.replace(/\/$/,'')||'/';
 return next!=='/'&&next!==page;
}
function eagleTransition(action,destination){
 const curtain=document.getElementById('eagle-curtain');if(!curtain||eagleReduceMotion()){action();return;}
 eagleTransitionBusy=true;
 const names={'/about':'ABOUT US','/services':'OUR SERVICES','/projects':'OUR PROJECTS','/request-a-quote':'REQUEST A QUOTE','/contact':'CONTACT','/admin':'ADMINISTRATION'};
 const path=new URL(destination||window.location.href,window.location.href).pathname.replace(/\/$/,'')||'/';
 const label=curtain.querySelector('.eagle-curtain-word');if(label)label.textContent=names[path]||'EAGLE CONSTRUCTION';
 curtain.className='eagle-curtain';void curtain.offsetHeight;curtain.classList.add('is-in');
 window.setTimeout(()=>{try{action();}finally{
   curtain.classList.remove('is-in');curtain.classList.add('is-out');
   window.setTimeout(()=>{curtain.className='eagle-curtain';eagleTransitionBusy=false;},620);
 }},510);
}
function eagleProgressUpdate(){
 const bar=document.getElementById('eagle-progress');if(!bar)return;
 const limit=Math.max(1,document.documentElement.scrollHeight-window.innerHeight);
 bar.style.transform='scaleX('+Math.max(0,Math.min(1,window.scrollY/limit))+')';
}
function eagleInitProgress(){
 if(eagleProgressInstalled)return;eagleProgressInstalled=true;
 window.addEventListener('scroll',eagleProgressUpdate,{passive:true});
 window.addEventListener('resize',eagleProgressUpdate,{passive:true});
}
function eagleLoadScript(src){
 return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.async=true;s.onload=resolve;s.onerror=()=>reject(new Error('Animation CDN unavailable'));document.head.appendChild(s);});
}
function eagleLoadMotionLibraries(){
 if(eagleMotionLibrariesRequested||eagleReduceMotion())return;eagleMotionLibrariesRequested=true;
 eagleLoadScript('https://cdn.jsdelivr.net/npm/gsap@3.15.0/dist/gsap.min.js')
 .then(()=>eagleLoadScript('https://cdn.jsdelivr.net/npm/gsap@3.15.0/dist/ScrollTrigger.min.js'))
 .then(()=>{if(!window.gsap||!window.ScrollTrigger)return;window.gsap.registerPlugin(window.ScrollTrigger);eagleMotionReady=true;eagleAnimatePage();})
 .catch(()=>eagleFallbackReveal());
 if(window.matchMedia('(min-width: 951px) and (hover: hover) and (pointer: fine)').matches)
   eagleLoadScript('https://cdn.jsdelivr.net/npm/lenis@1.3.27/dist/lenis.min.js').then(()=>{
     if(!window.Lenis||eagleSmoothScroll||eagleReduceMotion())return;
     eagleSmoothScroll=new window.Lenis({autoRaf:true,duration:1.12,smoothWheel:true,wheelMultiplier:.88});
     if(window.ScrollTrigger)eagleSmoothScroll.on('scroll',()=>window.ScrollTrigger.update());
   }).catch(()=>{});
}
function eagleSplitWords(element){
 if(!element||element.dataset.eagleSplit==='1')return;element.dataset.eagleSplit='1';
 const walker=document.createTreeWalker(element,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 nodes.forEach(node=>{if(!node.nodeValue.trim())return;const frag=document.createDocumentFragment();
   node.nodeValue.split(/(\s+)/).forEach(token=>{if(!token)return;
     if(/^\s+$/.test(token)){frag.appendChild(document.createTextNode(token));return;}
     const el=document.createElement('span');el.className='eagle-kinetic-word';el.textContent=token;frag.appendChild(el);
   });node.replaceWith(frag);
 });
}
function eagleFallbackReveal(){
 if(eagleMotionReady||eagleReduceMotion()||!('IntersectionObserver' in window))return;
 const nodes=document.querySelectorAll('.service-card,.project-photo,.special-card,.process-step,.quote-banner,.visit-banner');
 const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('eagle-fallback-show');io.unobserve(e.target);}}),{threshold:.06,rootMargin:'0px 0px -3% 0px'});
 nodes.forEach(n=>{n.classList.add('eagle-fallback-hide');io.observe(n);});
}
function eagleAnimatePage(){
 if(!eagleMotionReady||eagleReduceMotion()||!document.querySelector('#main'))return;
 if(eagleAnimationContext){eagleAnimationContext.revert();eagleAnimationContext=null;}
 const gsap=window.gsap,Trigger=window.ScrollTrigger;
 eagleAnimationContext=gsap.context(()=>{
   document.querySelectorAll('.hero h1,.section-heading h2,.intro-grid h2,.section-split h2,.people-copy h2,.benefits-grid h2,.heading-row h2').forEach(eagleSplitWords);
   document.querySelectorAll('.hero h1').forEach(h=>{
     gsap.from(h.querySelectorAll('.eagle-kinetic-word'),{yPercent:95,rotationX:50,opacity:0,stagger:.064,duration:.96,ease:'back.out(1.65)',clearProps:'all',delay:.13});
   });
   document.querySelectorAll('.section-heading h2,.intro-grid h2,.section-split h2,.people-copy h2,.benefits-grid h2,.heading-row h2').forEach((h,i)=>{
     const words=h.querySelectorAll('.eagle-kinetic-word');if(!words.length)return;
     gsap.from(words,{yPercent:104,rotationX:45,opacity:0,stagger:.04,duration:.78,ease:'back.out(1.5)',clearProps:'all',scrollTrigger:{trigger:h,start:'top 88%',once:true,id:'eagle-h-'+i}});
   });
   ['.service-cards','.project-gallery','.project-page-grid','.special-grid','.process-steps','.values-grid'].forEach((sel,g)=>{
     document.querySelectorAll(sel).forEach((box,i)=>{const children=[...box.children].filter(el=>!el.classList.contains('step-arrow'));if(!children.length)return;
       gsap.from(children,{y:52,opacity:.05,rotationX:8,stagger:.105,duration:.91,ease:'power3.out',clearProps:'all',scrollTrigger:{trigger:box,start:'top 89%',once:true,id:'eagle-group-'+g+'-'+i}});
     });
   });
   document.querySelectorAll('.quote-banner,.visit-banner,.people-section,.contact-information,.benefits').forEach((el,i)=>{
     gsap.from(el,{y:33,opacity:.18,duration:1.1,ease:'power2.out',clearProps:'all',scrollTrigger:{trigger:el,start:'top 90%',once:true,id:'eagle-section-'+i}});
   });
   document.querySelectorAll('.hero-image').forEach(el=>gsap.fromTo(el,{yPercent:-2},{yPercent:7,ease:'none',scrollTrigger:{trigger:el.closest('.hero'),start:'top top',end:'bottom top',scrub:.9,id:'eagle-hero-parallax'}}));
   document.querySelectorAll('.service-photo img,.project-photo img').forEach((el,i)=>gsap.fromTo(el,{scale:1.05,yPercent:-2},{scale:1.08,yPercent:2,ease:'none',scrollTrigger:{trigger:el.closest('.service-photo,.project-photo'),start:'top bottom',end:'bottom top',scrub:1.1,id:'eagle-photo-'+i}}));
   document.querySelectorAll('.eyebrow').forEach((el,i)=>gsap.from(el,{x:-12,opacity:.25,duration:.68,ease:'power2.out',clearProps:'all',scrollTrigger:{trigger:el,start:'top 94%',once:true,id:'eagle-kicker-'+i}}));
 },document.querySelector('#app'));
 window.requestAnimationFrame(()=>{Trigger.refresh();eagleProgressUpdate();});
}
function eagleAfterRender(){
 eagleInitProgress();eagleProgressUpdate();
 if(!eagleInitialLoaderStarted){
   eagleInitialLoaderStarted=true;const loader=document.getElementById('eagle-opening');
   if(loader){window.setTimeout(()=>loader.classList.add('is-done'),1350);window.setTimeout(()=>loader.remove(),2300);}
 }
 if(eagleSmoothScroll){eagleSmoothScroll.resize();if(!window.location.hash)eagleSmoothScroll.scrollTo(0,{immediate:true});}
 if(eagleMotionReady)eagleAnimatePage();else eagleLoadMotionLibraries();
}

window.addEventListener('popstate',()=>{if(eagleShouldTransition(location.pathname))eagleTransition(render,location.pathname);else render();});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(menuOpen)eagleCloseMenu();closeModal();}});
render();
